icate":{"description":"The collection predicate whose membership is declared.","type":"string"},"record_kind":{"const":"completeness","type":"string"},"scope":{"$ref":"#/$defs/Scope"},"subject":{"$ref":"#/$defs/RecordRef"},"validity":{"$ref":"#/$defs/Validity"}},"required":["record_kind","subject","predicate","members","completeness","validity","scope"],"type":"object"},{"additionalProperties":false,"description":"An authorial creative boundary over a named area (spec §8.4).","properties":{"area":{"$ref":"#/$defs/BoundaryArea","description":"The area: a record or a predicate/subject pattern."},"constraints":{"description":"Constraints that apply when the mode allows material.","items":{"$ref":"#/$defs/Expr"},"type":"array"},"key":{"type":"string"},"mode":{"$ref":"#/$defs/BoundaryMode"},"record_kind":{"const":"boundary","type":"string"},"scope":{"$ref":"#/$defs/Scope"},"validity":{"$ref":"#/$defs/Validity"}},"required":["record_kind","key","area","mode","validity","scope"],"type":"object"},{"additionalProperties":false,"description":"A typed, declarative rule (spec §9.3, §27.2).","properties":{"applicability":{"$ref":"#/$defs/Applicability","description":"Where the rule applies (universe-wide / worlds / conditional /\nunspecified)."},"capabilities":{"description":"Evaluator capabilities required; an unevaluable rule lists\nunsupported ones (spec §27.10).","items":{"type":"string"},"type":"array"},"channelChronology":{"anyOf":[{"$ref":"#/$defs/ChannelChronology"},{"type":"null"}]},"commitPolicy":{"$ref":"#/$defs/CommitPolicy"},"executable":{"description":"Whether the evaluator can execute this rule (set at compile time).","type":"boolean"},"expression":{"$ref":"#/$defs/Expr"},"key":{"type":"string"},"kind":{"$ref":"#/$defs/RuleKind"},"knowledgeBoundary":{"anyOf":[{"$ref":"#/$defs/KnowledgeBoundary"},{"type":"null"}]},"knowledgePolicy":{"anyOf":[{"$ref":"#/$defs/KnowledgePolicy"},{"type":"null"}]},"labels":{"additionalProperties":{"type":"string"},"type":"object"},"nam