pe":"array"},"history_coverage":{"anyOf":[{"$ref":"#/$defs/Coverage"},{"type":"null"}]},"records":{"items":{"$ref":"#/$defs/RecordVersion"},"type":"array"},"summaries":{"items":{"$ref":"#/$defs/RecordSummary"},"type":"array"}},"required":["records"],"type":"object"},"RelationCardinality":{"additionalProperties":false,"description":"Authored maximum across relation instances, independent of local multiplicity.","properties":{"countedRole":{"type":"string"},"grouping":{"$ref":"#/$defs/CardinalityKey"},"maximum":{"format":"uint32","minimum":0,"type":"integer"},"relation":{"$ref":"#/$defs/RecordRef"},"scope":{"$ref":"#/$defs/Scope"},"validity":{"$ref":"#/$defs/Validity"}},"required":["relation","grouping","countedRole","maximum","scope","validity"],"type":"object"},"RepresentedContextKind":{"description":"A represented context (spec §27.3): a dream, myth, quotation, or\nembedded story is not automatically objective reality.","oneOf":[{"additionalProperties":false,"description":"The objective reality of this universe.","properties":{"kind":{"const":"objective","type":"string"}},"required":["kind"],"type":"object"},{"additionalProperties":false,"description":"A character's represented beliefs/knowledge.","properties":{"holder":{"$ref":"#/$defs/RecordRef"},"kind":{"const":"character","type":"string"}},"required":["kind","holder"],"type":"object"},{"additionalProperties":false,"description":"A source's depicted narrative.","properties":{"kind":{"const":"source","type":"string"},"source":{"$ref":"#/$defs/RecordRef"}},"required":["kind","source"],"type":"object"},{"additionalProperties":false,"description":"A narrator's account.","properties":{"kind":{"const":"narrator","type":"string"},"narrator":{"$ref":"#/$defs/RecordRef"}},"required":["kind","narrator"],"type":"object"},{"additionalProperties":false,"description":"Another authored context (dream, myth, embedded story).","properties":{"kind":{"const":"authored","type":"string"},"label":{"type":"string"}},"required":["kind"