dity","basis"],"type":"object"},{"additionalProperties":false,"description":"An observation: presence alone does not establish perception or\nunderstanding (spec §27.6).","properties":{"basis":{"$ref":"#/$defs/EvidenceBasis"},"interpretation":{"anyOf":[{"$ref":"#/$defs/RecordRef"},{"type":"null"}],"description":"The interpreted proposition, if any."},"observed":{"$ref":"#/$defs/RecordRef"},"observer":{"$ref":"#/$defs/RecordRef"},"record_kind":{"const":"observation","type":"string"},"sensoryAccess":{"description":"Whether sensory access is established.","type":"boolean"},"time":{"$ref":"#/$defs/TemporalExpression"}},"required":["record_kind","observer","observed","sensoryAccess","time","basis"],"type":"object"},{"additionalProperties":false,"description":"A communication: knowledge changes need receipt and the declared\nacquisition/interpretation basis (spec §27.6).","properties":{"actualRecipients":{"items":{"$ref":"#/$defs/RecordRef"},"type":"array"},"channel":{"type":["string","null"]},"content":{"items":{"$ref":"#/$defs/RecordRef"},"type":"array"},"distorted":{"type":"boolean"},"intendedRecipients":{"items":{"$ref":"#/$defs/RecordRef"},"type":"array"},"receivedAt":{"anyOf":[{"$ref":"#/$defs/TemporalExpression"},{"type":"null"}]},"record_kind":{"const":"communication","type":"string"},"sender":{"$ref":"#/$defs/RecordRef"},"sentAt":{"$ref":"#/$defs/TemporalExpression"}},"required":["record_kind","sender","intendedRecipients","actualRecipients","content","sentAt","distorted"],"type":"object"},{"additionalProperties":false,"description":"A memory: remembered content can be false, incomplete, or detached\nfrom objective events (spec §27.6).","properties":{"accessibility":{"type":"string"},"alleged":{"anyOf":[{"$ref":"#/$defs/RecordRef"},{"type":"null"}]},"altered":{"type":"boolean"},"content":{"$ref":"#/$defs/RecordRef"},"holder":{"$ref":"#/$defs/RecordRef"},"record_kind":{"const":"memory","type":"string"},"validity":{"$ref":"#/$defs/Validity"}},"required":["record_ki