w.","properties":{"narrator":{"$ref":"#/$defs/RecordId"}},"required":["narrator"],"type":"object"},{"const":"reader","description":"Reader disclosure position.","type":"string"}]},"PlanStatus":{"enum":["active","abandoned","achieved"],"type":"string"},"Polarity":{"description":"Support or refutation of a proposition (spec §5.2).","enum":["support","refutation"],"type":"string"},"Precision":{"description":"Explicit precision alternatives (spec §27.2). An estimate is never\nsilently converted into an exact value or a probability distribution.","enum":["exact","approximate","range","one_of","unresolved"],"type":"string"},"PrincipalId":{"description":"Stable identity of an authenticated application principal.","pattern":"^prn_[0-9a-f]{24}$","type":"string"},"PropositionRole":{"additionalProperties":false,"properties":{"participant":{"$ref":"#/$defs/RecordRef"},"role":{"type":"string"}},"required":["role","participant"],"type":"object"},"Quantification":{"description":"Quantification over a proposition (spec §27.3).","oneOf":[{"const":"particular","description":"\"The gate is in the ruins\" — a particular claim.","type":"string"},{"const":"universal","description":"\"All X have Y\".","type":"string"},{"const":"exists","description":"\"Some X has Y\".","type":"string"}]},"Quantifier":{"description":"A named binding in an expression environment.","enum":["for_all","exists"],"type":"string"},"RecordId":{"description":"Stable identity of a canonical record within a universe.","pattern":"^rec_[0-9a-f]{24}$","type":"string"},"RecordIdentity":{"additionalProperties":false,"description":"The identity of a canonical record (spec §27.1 contract table:\n`universe_id`, `record_id`, `record_kind`). Identity and kind are\nimmutable.","properties":{"record_id":{"$ref":"#/$defs/RecordId"},"record_kind":{"$ref":"#/$defs/RecordKind"},"universe_id":{"$ref":"#/$defs/UniverseId"}},"required":["universe_id","record_id","record_kind"],"type":"object"},"RecordKind":{"description":"The kind of a