_digest"],"type":"object"},"RecordVersionId":{"description":"Stable identity of an immutable record version.","pattern":"^ver_[0-9a-f]{24}$","type":"string"},"RelationCardinality":{"additionalProperties":false,"description":"Authored maximum across relation instances, independent of local multiplicity.","properties":{"countedRole":{"type":"string"},"grouping":{"$ref":"#/$defs/CardinalityKey"},"maximum":{"format":"uint32","minimum":0,"type":"integer"},"relation":{"$ref":"#/$defs/RecordRef"},"scope":{"$ref":"#/$defs/Scope"},"validity":{"$ref":"#/$defs/Validity"}},"required":["relation","grouping","countedRole","maximum","scope","validity"],"type":"object"},"RepresentedContextKind":{"description":"A represented context (spec §27.3): a dream, myth, quotation, or\nembedded story is not automatically objective reality.","oneOf":[{"additionalProperties":false,"description":"The objective reality of this universe.","properties":{"kind":{"const":"objective","type":"string"}},"required":["kind"],"type":"object"},{"additionalProperties":false,"description":"A character's represented beliefs/knowledge.","properties":{"holder":{"$ref":"#/$defs/RecordRef"},"kind":{"const":"character","type":"string"}},"required":["kind","holder"],"type":"object"},{"additionalProperties":false,"description":"A source's depicted narrative.","properties":{"kind":{"const":"source","type":"string"},"source":{"$ref":"#/$defs/RecordRef"}},"required":["kind","source"],"type":"object"},{"additionalProperties":false,"description":"A narrator's account.","properties":{"kind":{"const":"narrator","type":"string"},"narrator":{"$ref":"#/$defs/RecordRef"}},"required":["kind","narrator"],"type":"object"},{"additionalProperties":false,"description":"Another authored context (dream, myth, embedded story).","properties":{"kind":{"const":"authored","type":"string"},"label":{"type":"string"}},"required":["kind","label"],"type":"object"}]},"RequiredEvidence":{"additionalProperties":false,"description":"Exact source-category packs. No listed review method means no review duty.","properties":{"reviewMethods":{"items":{"$ref":"#/$defs/EvidenceReviewMethod"},"type":"array"},"sourceCategories":{"items":{"$ref":"#/$defs/VersionRef"},"type":"array"}},"required":["sourceCategories"],"type":"object"},"RevisionId":{"description":"Stable identity of an immutable canon revision.","pattern":"^rev_[0-9a-f]{24}$","type":"string"},"RoleDef":{"additionalProperties":false,"description":"A named role in a relation (spec §27.2): supports more than two roles\nand more than one participant per role where declared.","properties":{"multiplicity":{"$ref":"#/$defs/Multiplicity"},"name":{"type":"string"},"ordered":{"type":"boolean"},"participantTypes":{"default":[],"items":{"$ref":"#/$defs/RecordId"},"type":"array"}},"required":["name","multiplicity","ordered"],"type":"object"},"RuleKind":{"description":"Rule kinds with distinct semantics and commit policies (spec §9.3).\n\nSeverity, commit-blocking policy, and semantic type are distinct.","oneOf":[{"const":"structural_invariant","description":"Invalid record shape: always blocks commit; no author waiver.","type":"string"},{"const":"physical_constraint","description":"Cannot occur under established rules: blocks delegated commit\nunless a valid scoped exception or authorized revision resolves it.","type":"string"},{"const":"operational_requirement","description":"A specified action requires defined prerequisites.","type":"string"},{"const":"law","description":"Actors may violate it: a normative departure, not physical\nimpossibility.","type":"string"},{"const":"behavioral_tendency","description":"Typical rather than universal behavior: advisory only.","type":"string"},{"const":"authorial_restriction","description":"Controls permitted additions/revisions: enforced by scope and\nauthorization.","type":"string"},{"const":"descriptive","description":"Stored but not executable by this evaluator.","type":"string"}]},"SagaMembership":{"additionalProperties":false