ll"}]},"altered":{"type":"boolean"},"content":{"$ref":"#/$defs/RecordRef"},"holder":{"$ref":"#/$defs/RecordRef"},"validity":{"$ref":"#/$defs/Validity"}},"required":["holder","content","accessibility","altered","validity"],"type":"object"},"Multiplicity":{"enum":["single","multiple"],"type":"string"},"Observation":{"additionalProperties":false,"description":"An observation: presence alone does not establish perception or\nunderstanding (spec §27.6).","properties":{"basis":{"$ref":"#/$defs/EvidenceBasis"},"interpretation":{"anyOf":[{"$ref":"#/$defs/RecordRef"},{"type":"null"}],"description":"The interpreted proposition, if any."},"observed":{"$ref":"#/$defs/RecordRef"},"observer":{"$ref":"#/$defs/RecordRef"},"sensoryAccess":{"description":"Whether sensory access is established.","type":"boolean"},"time":{"$ref":"#/$defs/TemporalExpression"}},"required":["observer","observed","sensoryAccess","time","basis"],"type":"object"},"OccurrenceMode":{"description":"Event occurrence modes (spec §27.5).\n\nOnly an admitted `occurred` event establishes objective state effects\nby default. A report establishes a report, not the reported\noccurrence.","oneOf":[{"enum":["occurred","planned","predicted","hypothetical","reported"],"type":"string"},{"additionalProperties":false,"description":"Another declared descriptive mode.","properties":{"descriptive":{"additionalProperties":false,"properties":{"label":{"type":"string"}},"required":["label"],"type":"object"}},"required":["descriptive"],"type":"object"}]},"Operand":{"description":"An operand of an expression node.","oneOf":[{"additionalProperties":false,"description":"A variable bound by the rule scope or a quantifier.","properties":{"kind":{"const":"variable","type":"string"},"name":{"type":"string"}},"required":["kind","name"],"type":"object"},{"additionalProperties":false,"description":"Struct variants keep one canonical form per operand: the referenced\nrecord/value is nested under a named key, never inlined into the\ntagged map 