ng reader disclosure order."},"revision":{"$ref":"#/$defs/RevisionId"},"time":{"$ref":"#/$defs/FrameTime"},"universe":{"$ref":"#/$defs/UniverseId"}},"required":["universe","continuity","revision","context","time","perspective"],"type":"object"},"FrameTime":{"description":"The temporal part of a frame.","oneOf":[{"additionalProperties":false,"description":"All validities: the query makes no temporal claim (spec §27.1:\n\"an explicitly timeless/all-validities query\").","properties":{"kind":{"const":"timeless","type":"string"}},"required":["kind"],"type":"object"},{"additionalProperties":false,"description":"Evaluate at or within this temporal expression.","properties":{"kind":{"const":"at","type":"string"},"time":{"$ref":"#/$defs/TemporalExpression"}},"required":["kind","time"],"type":"object"},{"additionalProperties":false,"description":"State at the moment of a specific event (entry/exit framing\nis handled by the event's own time; this names the anchor).","properties":{"event":{"$ref":"#/$defs/RecordRef"},"kind":{"const":"at_event","type":"string"},"side":{"$ref":"#/$defs/EventTimeSide"}},"required":["kind","event","side"],"type":"object"}]},"OperationId":{"description":"Stable identity of a durable operation.","pattern":"^op_[0-9a-f]{24}$","type":"string"},"OpposingChain":{"additionalProperties":false,"properties":{"assertion":{"$ref":"#/$defs/RecordVersionId"},"assertion_id":{"$ref":"#/$defs/RecordId"},"complete":{"type":"boolean"},"dependencies":{"items":{"$ref":"#/$defs/VersionRef"},"type":"array"},"proposition":{"$ref":"#/$defs/RecordVersionId"},"proposition_id":{"$ref":"#/$defs/RecordId"}},"required":["assertion_id","proposition_id","assertion","proposition","dependencies","complete"],"type":"object"},"OpposingEvidence":{"additionalProperties":false,"properties":{"applicability":{"anyOf":[{"$ref":"#/$defs/Applicability"},{"type":"null"}]},"context":{"$ref":"#/$defs/RecordRef"},"coverage":{"$ref":"#/$defs/Coverage"},"diagnostic_version":{"type":"string"},"exception_versions":{"items":{"$ref":"#/$defs/RecordVersionId"},"type":"array"},"fingerprint":{"$ref":"#/$defs/FindingFingerprint"},"intersection":{"$ref":"#/$defs/OpposingIntersection"},"kind":{"$ref":"#/$defs/OpposingKind"},"policy_versions":{"items":{"$ref":"#/$defs/RecordVersionId"},"type":"array"},"proposition":{"$ref":"#/$defs/Proposition"},"realm":{"anyOf":[{"$ref":"#/$defs/RecordRef"},{"type":"null"}]},"refutation":{"$ref":"#/$defs/OpposingChain"},"support":{"$ref":"#/$defs/OpposingChain"},"unresolved_reasons":{"items":{"$ref":"#/$defs/OpposingReason"},"type":"array"}},"required":["diagnostic_version","fingerprint","kind","proposition","support","refutation","context","intersection","coverage","unresolved_reasons","policy_versions","exception_versions"],"type":"object"},"OpposingIntersection":{"oneOf":[{"additionalProperties":false,"properties":{"kind":{"const":"unqualified","type":"string"}},"required":["kind"],"type":"object"},{"additionalProperties":false,"properties":{"kind":{"const":"exact","type":"string"},"validity":{"$ref":"#/$defs/Validity"}},"required":["kind","validity"],"type":"object"},{"additionalProperties":false,"properties":{"guaranteed":{"anyOf":[{"$ref":"#/$defs/Validity"},{"type":"null"}]},"kind":{"const":"uncertain","type":"string"},"left":{"$ref":"#/$defs/Validity"},"right":{"$ref":"#/$defs/Validity"}},"required":["kind","left","right"],"type":"object"},{"additionalProperties":false,"properties":{"kind":{"const":"unresolved","type":"string"}},"required":["kind"],"type":"object"}]},"OpposingKind":{"enum":["definite","unresolved"],"type":"string"},"OpposingReason":{"enum":["equality","context","realm","worlds","time","precision","persistence","provenance","budget"],"type":"string"},"Perspective":{"description":"How a query views the universe (spec §8.3).\n\nAuthor-known truth, character perspective, and reader disclosure are\nseparate views. Author permissions are a security dimension; a\npoint-of-view filter is not an access-control mechanism unless the\nauthor explicitly configures a restricted principal.","oneOf":[{"const":"author","description":"The author's omniscient view of the universe.","type":"string"},{"additionalProperties":false,"description":"A character's fictional knowledge (bounded by records).","properties":{"character":{"$ref":"#/$defs/RecordId"}},"required":["character"],"type":"object"},{"additionalProperties":false,"description":"A source/narrator's depicted view.","properties":{"narrator":{"$ref":"#/$defs/RecordId"}},"required":["narrator"],"type":"object"},{"const":"reader","description":"Reader disclosure position.","type":"string"}]},"ProposalId":{"description":"Stable identity of a proposal.","pattern":"^prp_[0-9a-f]{24}$","type":"string"},"ProposalRef":{"additionalProperties":false,"properties":{"digest":{"type":"string"},"proposal_id":{"$ref":"#/$defs/ProposalId"},"version":{"format":"uint64","minimum":0,"type":"integer"}},"required":["proposal_id","version","digest"],"type":"object"},"Proposition":{"additionalProperties":false,"description":"A claimable statement (spec §5.2, §27.3).\n\nA proposition describes something that *may be* asserted; its existence\ndoes not assert its truth.","properties":{"context":{"$ref":"#/$defs/RecordRef","description":"The represented context this proposition lives in (objective\nreality, a character's beliefs, a source narrative, ...)."},"predicate":{"$ref":"#/$defs/RecordRef","description":"A property or relation definition record."},"quantification":{"$ref":"#/$defs/Quantification"},"roles":{"description":"Named role bindings for n-ary relations.","items":{"$ref":"#/$defs/PropositionRole"},"type":"array"},"subject":{"$ref":"#/$defs/RecordRef","description":"The entity claimed about."},"value":{"anyOf":[{"$ref":"#/$defs/Value"},{"type":"null"}],"description":"The value for property-shaped propositions."}},"required":["predicate","subject","quantification","context"],"type":"object"},"PropositionRole":{"additionalProperties":false,"properti