n"},"expression":{"$ref":"#/$defs/Expr"},"key":{"type":"string"},"kind":{"$ref":"#/$defs/RuleKind"},"knowledgeBoundary":{"anyOf":[{"$ref":"#/$defs/KnowledgeBoundary"},{"type":"null"}]},"knowledgePolicy":{"anyOf":[{"$ref":"#/$defs/KnowledgePolicy"},{"type":"null"}]},"labels":{"additionalProperties":{"type":"string"},"type":"object"},"namespace":{"type":"string"},"relationCardinality":{"anyOf":[{"$ref":"#/$defs/RelationCardinality"},{"type":"null"}]},"requiredEvidence":{"anyOf":[{"$ref":"#/$defs/RequiredEvidence"},{"type":"null"}]},"subjectTypes":{"description":"Subject types the rule constrains (empty = any).","items":{"$ref":"#/$defs/RecordId"},"type":"array"},"targetPredicates":{"description":"The predicates this rule concerns (for applicability enumeration;\nspec §9.5: the evaluator enumerates applicable rules from\nstructured indexes, never only search matches).","items":{"type":"string"},"type":"array"},"validity":{"$ref":"#/$defs/Validity","description":"Temporal validity of the rule itself (S35: jurisdictional scoping)."}},"required":["namespace","key","labels","kind","commitPolicy","applicability","targetPredicates","expression","capabilities","executable","validity"],"type":"object"},"RuleKind":{"description":"Rule kinds with distinct semantics and commit policies (spec §9.3).\n\nSeverity, commit-blocking policy, and semantic type are distinct.","oneOf":[{"const":"structural_invariant","description":"Invalid record shape: always blocks commit; no author waiver.","type":"string"},{"const":"physical_constraint","description":"Cannot occur under established rules: blocks delegated commit\nunless a valid scoped exception or authorized revision resolves it.","type":"string"},{"const":"operational_requirement","description":"A specified action requires defined prerequisites.","type":"string"},{"const":"law","description":"Actors may violate it: a normative departure, not physical\nimpossibility.","type":"string"},{"const":"behavioral_tendency","description":"Typical rather than universal behavior: advisory only.","type":"string"},{"const":"authorial_restriction","description":"Controls permitted additions/revisions: enforced by scope and\nauthorization.","type":"string"},{"const":"descriptive","description":"Stored but not executable by this evaluator.","type":"string"}]},"Saga":{"additionalProperties":false,"description":"A saga/series: typed membership and ordering, non-exclusive (spec §5.6,\n§36.7).","properties":{"labels":{"additionalProperties":{"type":"string"},"type":"object"},"memberships":{"items":{"$ref":"#/$defs/SagaMembership"},"type":"array"},"title":{"type":"string"}},"required":["title","labels","memberships"],"type":"object"},"SagaMembership":{"additionalProperties":false,"properties":{"order":{"description":"Authored ordering position (nullable = unordered).","format":"uint64","minimum":0,"type":["integer","null"]},"role":{"type":"string"},"work":{"$ref":"#/$defs/RecordRef"}},"required":["work","role"],"type":"object"},"SceneRef":{"additionalProperties":false,"description":"A scene reference: reader order, narration time, depicted event time,\nand local world time stay separate (spec §36.7).","properties":{"depictedEvents":{"items":{"$ref":"#/$defs/RecordRef"},"type":"array"},"disclosedRecords":{"description":"Explicit reader disclosures; depicted events alone do not establish knowledge.","items":{"$ref":"#/$defs/RecordRef"},"type":"array"},"narrationFrame":{"anyOf":[{"$ref":"#/$defs/RecordRef"},{"type":"null"}]},"narrativePosition":{"format":"uint64","minimum":0,"type":["integer","null"]},"sceneId":{"type":"string"},"viewpoint":{"anyOf":[{"$ref":"#/$defs/RecordRef"},{"type":"null"}]},"workVersion":{"$ref":"#/$defs/VersionRef"},"worldAssociations":{"items":{"$ref":"#/$defs/WorldAssociation"},"type":"array"}},"required":["workVersion","sceneId","depictedEvents","worldAssociations"],"type":"object"},"Scope":{"additionalProperties":false,"description":"The scope of an assertion or rule: applicability + represented context\n+ optional realm (spec §27.3).","properties":{"applicability":{"$ref":"#/$defs/Applicability"},"context":{"$ref":"#/$defs/RecordRef","description":"The represented context record (objective reality, a character,\na source narrative, ...). Required: every assertion states its\ncontext explicitly."},"realm":{"anyOf":[{"$ref":"#/$defs/RecordRef"},{"type":"null"}],"description":"Optional realm (an authored physical/metaphysical domain)."}},"required":["applicability","context"],"type":"object"},"Secret":{"additionalProperties":false,"description":"A secret/disclosure constraint (spec §27.6).\n\nFictional secrecy and application access grants remain separate.","properties":{"concealment":{"type":["string","null"]},"fictionalKnowers":{"items":{"$ref":"#/$defs/RecordRef"},"type":"array"},"readerDisclosed":{"type":"boolean"},"scope":{"items":{"$ref":"#/$defs/RecordRef"},"type":"array"},"validity":{"$ref":"#/$defs/Validity"}},"required":["scope","fictionalKnowers","readerDisclosed","validity"],"type":"object"},"Selector":{"maxLength":256,"minLength":1,"pattern":"^[^\\s*/\\\\][^*/\\\\]*$","type":"string"},"Sha256Hex":{"description":"Owning decoder enforces the same exact digest shape as the JSON schema.","pattern":"^[0-9a-f]{64}$","type":"string"},"SpatialExpression":{"description":"A qualitative spatial expression (spec §7.4).\n\nOwnership, custody, containment, control, occupancy, legal access,\nphysical access, and knowledge of an entrance are separate predicates:\nonly the qualitative relations below live in values; the predicates\nthemselves are definitions.","oneOf":[{"additionalProperties":false,"properties":{"kind":{"const":"contained_in","type":"string"},"target":{"$ref":"#/$defs/RecordRef"}},"required":["kind","target"],"type":"object"},{"additionalProperties":false,"properties":{"kind":{"const":"adjacent_to","type":"string"},"target":{"$ref":"#/$defs/RecordRef"}},"required":["kind","target"],"type":"object"},{"additionalProperties":false,"properties":{